// Pseudo-evaluation snippet for latency/energy estimates
function estimatePostModeration(postBytes, modelSizeMB) {
  const latencyMs = 0.004 * postBytes + 0.5 * modelSizeMB;
  const energyJ = latencyMs * 0.01;
  return { latencyMs, energyJ };
}
```

